-- Sets one-line cue + description (by exercise id) and demo_video_url (by name) on global exercises only.

update exercises set cue = 'Sit with both knees bent at right angles, then lean your chest over the front shin.', description = 'Sit on the floor with your front shin in front of you and your back leg bent out to the side. Keep both knees at about 90 degrees. Sit tall, then lean forward over the front shin until you feel it in the front hip. Don''t let your back hip lift off the floor. Hold, then switch legs.' where id = '41bd7339-91c4-4e77-9b1c-1e6561ad00ed' and owner_id is null;
update exercises set cue = 'Sit in 90/90, then rotate both knees over to the other side without using your hands.', description = 'Start seated with both knees bent at right angles, one leg in front and one to the side. Lift your knees and swing them across so the legs swap places. Keep your chest tall the whole time. Don''t push off the floor with your hands. Do the reps one way, then the other.' where id = 'ac508d2c-52a1-45a5-8d02-f7a46472f2eb' and owner_id is null;
update exercises set cue = 'Lie on your back, loop a strap around one foot, and lift that straight leg as high as you can.', description = 'Lie flat with one leg straight on the floor. Wrap the strap around the other foot and raise that leg with the knee straight. Use your leg muscles to lift it, and let the strap only guide you. Hold at the top for 15 seconds. Don''t let the bottom leg roll out or the knee bend. Then switch legs.' where id = 'df029f0e-dd4f-434d-a8ce-799e6a9e0a97' and owner_id is null;
update exercises set cue = 'Sit with your legs wide apart and slowly lean forward, keeping your knees pointing at the ceiling.', description = 'Sit on a mat with your legs spread as wide as is comfortable. Put your hands on the floor in front of you and walk them forward. Keep your back long, and your toes and kneecaps pointing up. Stop where you feel a pull on the inner thighs. Don''t round your back to get lower.' where id = '325cb9e1-9c61-47e9-93c8-34225d11a778' and owner_id is null;
update exercises set cue = 'Lift one foot and draw big slow circles with your toes, moving only the ankle.', description = 'Sit or stand holding one foot off the floor. Trace the biggest circle you can with your toes. Keep your leg still so only the ankle moves. Go slowly and smoothly, and try not to rush the top of the circle. Switch directions halfway, then switch feet.' where id = '65cbe33a-5fb0-44b3-9cec-1285875257cc' and owner_id is null;
update exercises set cue = 'Loop a band around your foot, then turn the sole outward against the pull.', description = 'Sit with your leg out and a band anchored on the inside of your foot. Pull the band around the outside of your forefoot. Turn the sole of the foot out and away, then return slowly. Keep your knee and lower leg still. Don''t let the band snap you back. Finish the reps, then switch feet.' where id = 'e3f51f04-1cc2-42a3-8cbc-cf100ee5071b' and owner_id is null;
update exercises set cue = 'Sit with a band anchored in front, then turn your foot inward and pull your toes toward your shin.', description = 'Sit with your leg out and the band pulling your foot away and out. Pull your toes up toward your shin while turning the sole inward. Hold for a beat, then go back slowly. Keep your knee still and let only the ankle move. Don''t rush the return. Finish the reps, then switch feet.' where id = '21e5d812-5cb5-4e11-b30a-4e0fc6472f15' and owner_id is null;
update exercises set cue = 'Tie a band around your front ankle and push your knee forward over your toes, keeping the heel down.', description = 'Stand facing a wall with a band pulling your ankle back. Put one foot forward, toes a few inches from the wall. Drive your knee toward the wall without lifting the heel. Move it back, and keep your knee tracking over the middle toes. Don''t let your arch collapse. Then switch feet.' where id = '7f18c8c6-af30-476c-979e-670f404e8e6e' and owner_id is null;
update exercises set cue = 'Put a band above your knees, bend a little, and step sideways while keeping your feet pointing forward.', description = 'Place the band around your legs and drop into a quarter squat. Step out to the side with the lead foot, then bring the other foot in. Keep your toes pointing forward and the tension on the band the whole time. Don''t let your knees cave in. Go one direction, then come back the other way.' where id = '58f93b54-a6dc-4d29-992f-01c071e09fc0' and owner_id is null;
update exercises set cue = 'Drop into a deep squat, sit low, and keep both heels flat on the floor.', description = 'Stand with your feet about shoulder-width apart and toes turned out a little. Lower into the deepest squat you can with your heels down. Put your elbows inside your knees and press them out. Keep your chest up. If your heels lift, hold onto something or put a small plate under them.' where id = 'cc21ca30-89cc-4346-aea7-af01acd9d652' and owner_id is null;
update exercises set cue = 'Lie on your side, keep the top leg straight, and lift it up and slightly back, then lower slowly.', description = 'Lie on your side with your bottom knee bent for balance. Keep the top leg straight and your toes pointing forward. Lift the leg to about hip height, then lower it with control. Don''t roll your hips backward to get higher. Finish the reps, then switch sides.' where id = 'f29272d3-0950-45ce-a12b-7d7f9a9743e5' and owner_id is null;
update exercises set cue = 'Stand on one foot on a foam pad and slowly turn your head left and right.', description = 'Stand barefoot on a foam pad on one leg with a soft knee. Pick a spot ahead and look at it first. Then turn your head slowly left, back to centre, then right. Keep your hips level and your body quiet. If you wobble, tap the other toe down and go again. Then switch legs.' where id = '94fcd815-a788-4fe0-9e71-d75cad4ffeb7' and owner_id is null;
update exercises set cue = 'Stand on one foot, close your eyes, and stay as still as you can.', description = 'Stand barefoot on a flat floor on one leg. Keep a slight bend in the knee and your hips level. Close your eyes once you feel steady. Let your foot make small adjustments. If you lose balance, open your eyes and start again. Then switch legs.' where id = '5c38f903-16ba-465c-bafa-69c3ca3841e1' and owner_id is null;
update exercises set cue = 'Stand on one foot on a foam pad, close your eyes, and keep your body still.', description = 'Step onto the foam pad barefoot and lift the other foot. Keep your knee soft and your hips level. Find your balance with your eyes open, then close them. Expect the foot to work hard underneath you. Don''t grab for the wall unless you have to. Then switch legs.' where id = '9fc082ec-8d3d-4f21-9f81-4b2a4924f61f' and owner_id is null;
update exercises set cue = 'Stand on one foot, rise onto your toes as high as you can, and lower slowly.', description = 'Stand tall on one leg with a finger on a wall if you need it. Push up through the ball of your foot until you''re as high as you can go. Pause for a second at the top. Lower slowly over three seconds. Don''t let the ankle roll out to the side. Then switch legs.' where id = 'b9a88595-e470-45b6-bd0c-3405fefa0af1' and owner_id is null;
update exercises set cue = 'Walk forward on your toes, then walk back on your heels, taking small steady steps.', description = 'Pick a straight 20 meters of floor. Rise onto your toes and walk to the far end. Then turn around and walk back on your heels with your toes lifted. Keep your steps short and your posture tall. Don''t let your ankles wobble in or out.' where id = 'b94a0cff-9df0-42d5-99d9-f03847b179cb' and owner_id is null;
update exercises set cue = 'Stand with your back against a wall, feet out front, and lift your toes toward your shins.', description = 'Lean your back on a wall with your feet about a foot and a half out. Keep your legs straight and your heels planted. Pull your toes up as high as they''ll go, then lower slowly. Keep the movement at the ankle and don''t bend the knees. Count each one.' where id = '4975fe52-47c7-411c-9a0a-6bac277f7a93' and owner_id is null;
update exercises set cue = 'Hold a dumbbell, stand on one leg on a step with the knee bent, and rise onto your toes.', description = 'Stand with the ball of one foot on the step and the heel hanging off. Hold a dumbbell at your side and bend your knee slightly. Drop the heel below the step, then drive up as high as you can. Keep the knee bend the same the whole set. Don''t bounce at the bottom. Then switch legs.' where id = 'e7b3ff67-465e-4704-9e13-62d50306d322' and owner_id is null;
update exercises set cue = 'Hold a dumbbell, stand on one leg on a step with the knee straight, and rise onto your toes.', description = 'Stand with the ball of one foot on the step and the heel hanging off. Hold a dumbbell in the hand on the same side as the working leg. Lower the heel down slowly, then push up as high as you can with the knee locked straight. Pause at the top. Don''t lean forward to cheat. Then switch legs.' where id = '0271ffa8-a641-452e-bf51-92f4ea18ac49' and owner_id is null;
update exercises set cue = 'Stand on one foot on a wobble board and keep the edges from touching the floor.', description = 'Place the wobble board on a flat floor and step on with one foot. Find the middle where the board sits level. Keep your knee soft and your eyes ahead. Small quick corrections are fine. If the edge hits the floor, reset and go again. Then switch legs.' where id = 'e6c7da2c-aa8e-40d2-a101-cc8b12b3e5db' and owner_id is null;
update exercises set cue = 'Get on hands and knees, then reach one arm and the opposite leg out long and level.', description = 'Start on all fours, hands under shoulders and knees under hips. Slide one leg back and reach the opposite arm forward until they''re both straight. Keep your hips and shoulders square to the floor. Don''t let your lower back sag. Pause, return, and then do the other side.' where id = '7526e815-814a-44d3-bd45-1f5df7ed33f9' and owner_id is null;
update exercises set cue = 'Rest your back foot on a bench, then lower straight down on the front leg, dumbbells in hand.', description = 'Stand a big step in front of a bench and put the top of one foot on it. Hold a dumbbell in each hand. Lower your back knee toward the floor, keeping your torso upright. Push through the front foot to stand. Don''t let your front knee drift in. Finish the reps, then switch legs.' where id = '0230e799-8c47-4ca5-b7a2-2d68f68a1a98' and owner_id is null;
update exercises set cue = 'Put your back knee on the floor, foot up a wall or couch, and squeeze your glute to stand tall.', description = 'Kneel with one knee near the wall and your shin and foot against it. Plant the other foot out in front in a lunge. Squeeze the back-leg glute and lift your chest until you feel a stretch at the front of the hip. Don''t arch your lower back. Hold, then switch sides.' where id = '381115fb-eb11-491e-a199-60bea0e72e63' and owner_id is null;
update exercises set cue = 'Lie on your back, arms up, knees over hips, then lower opposite arm and leg slowly.', description = 'Lie on your back with your arms straight up and your knees bent at 90 degrees. Press your lower back gently into the floor. Reach one arm back overhead and lower the opposite leg toward the floor. Don''t let your back arch up. Return and swap sides.' where id = '608ce2f5-9dd3-4aaf-867f-42319ba81b85' and owner_id is null;
update exercises set cue = 'Lie on your back with knees bent, lift your head and shoulders a little, and hold.', description = 'Lie on your back with your knees bent and feet flat. Put your hands under your lower back to keep the natural curve. Lift your head and shoulders just a few inches off the floor. Hold for eight seconds, then lower slowly. Don''t pull on your neck.' where id = 'e50ab2b2-1b87-4c23-9b05-f42b8cf9132a' and owner_id is null;
update exercises set cue = 'Hold a dumbbell in each hand, push your hips back, and lower until you feel your hamstrings.', description = 'Stand tall with the dumbbells in front of your thighs. Soften your knees and push your hips back like closing a car door. Keep your back flat and the weights close to your legs. Stop when you feel the stretch in the backs of your thighs. Squeeze your glutes to stand. Don''t round your back.' where id = 'c416732c-6a1a-4b02-b717-6e01236fd62f' and owner_id is null;
update exercises set cue = 'Lie on your side, prop up on your forearm, and lift your hips into a straight line.', description = 'Lie on your side with your elbow under your shoulder and your legs stacked. Lift your hips until your body is straight from head to feet. Keep your hips from sagging or twisting forward. Hold for the full time, then lower and switch sides.' where id = '7f1c6bcc-b275-4bfa-bada-53e0d5e2bb4d' and owner_id is null;
update exercises set cue = 'Lie on your back with one foot flat, lift the other leg straight, and drive your hips up.', description = 'Lie on your back with one knee bent and that foot flat on the floor. Extend the other leg straight in the air. Press through the planted heel and lift your hips until your body is in a straight line. Don''t let your hips tilt or your back arch. Lower slowly, then switch legs.' where id = 'ade59796-7100-487f-8b37-cf4448b5675e' and owner_id is null;
update exercises set cue = 'Hold your arms out to the sides and draw large slow circles.', description = 'Stand tall with your arms out at shoulder height. Make circles with the arms, starting small and growing bigger. Keep your shoulders away from your ears. Go ten one way, then ten the other. Don''t swing wildly or arch your lower back.' where id = '4dfbd6a0-0dfb-493c-ad40-06122cdbc5ab' and owner_id is null;
update exercises set cue = 'Drop into a deep squat with your feet flat and just stay there, relaxed.', description = 'Stand with your feet wider than your hips and your toes turned out. Sit down between your knees as low as you can with your heels flat. Put your palms together and press your elbows against your knees. Keep your chest up and breathe slowly. If it''s too hard, hold onto a post or doorframe.' where id = '04f00b8b-5356-46c8-9959-fbe696989399' and owner_id is null;
update exercises set cue = 'Hold a band in front of you and pull your hands apart until it touches your chest.', description = 'Stand with your arms straight out in front at chest height, holding the band with an overhand grip. Pull your hands apart, squeezing your shoulder blades together. Bring the band to your chest if you can. Keep your ribs down. Don''t shrug. Let the band back slowly.' where id = '48200d34-b90e-4293-a899-2780c17dc89b' and owner_id is null;
update exercises set cue = 'Loop a band around your ankle and let it pull you gently backward while you hold.', description = 'Anchor the band low and loop it around the front of the ankle, with it pulling you back. Step away until there is steady tension. Rock your weight forward over the foot, keeping the heel down. Do ten pulses, then hold for 30 to 60 seconds. Then switch feet.' where id = '8e4630cf-ea82-4f91-ba60-27b2d98b7fc2' and owner_id is null;
update exercises set cue = 'Hold a band, elbow against your side, and rotate your forearm outward.', description = 'Stand with a band anchored at elbow height and your elbow tucked into your side, bent at 90 degrees. Rotate your hand outward, away from your belly. Keep the elbow pinned. Don''t twist your body to help. Return slowly, then switch arms.' where id = '918e4a8e-037d-45e2-a7f3-a8b91efc3a82' and owner_id is null;
update exercises set cue = 'Stand on a Bosu ball on one foot and stay still.', description = 'Stand beside the Bosu and step onto the middle of it with one foot. Lift the other foot and balance. Keep your knee slightly bent and your eyes on a fixed spot. Make small corrections with your foot. Don''t let the edge of the ball touch the floor. Then switch legs.' where id = 'd796261b-b65a-41a9-8f12-53dd4490ad3a' and owner_id is null;
update exercises set cue = 'Stand on the Bosu with both feet and squat down and back up under control.', description = 'Stand on the flat side of the Bosu ball with your feet shoulder-width apart. Squat down, pushing your hips back and keeping your heels down. Go as deep as you can control, then stand. Keep your knees in line with your toes. Don''t rush. If it''s too easy, hold a weight at your chest.' where id = '0fc294f5-d9c5-42b8-914e-eee456a97515' and owner_id is null;
update exercises set cue = 'Lie the calf on a foam roller and roll slowly from ankle to knee.', description = 'Sit with your calf on top of the foam roller. Lift your hips off the floor with your hands. Roll slowly from just above the ankle up to below the knee. Stop and breathe on any tender spot. Cross the other leg over for more pressure. Then switch legs.' where id = 'cca300de-f82f-4a57-87a7-cb1cd6d6a22e' and owner_id is null;
update exercises set cue = 'Stand on one foot on a step, close your eyes, and rise onto your toes slowly.', description = 'Stand on one foot on the edge of a step with the other foot lifted. Hold a rail lightly if you need it. Rise onto the ball of the foot, then lower slowly. Close your eyes once you feel steady. Don''t let the ankle roll. Then switch legs.' where id = 'c9ef2252-d4ae-4de7-bcd5-342d94fee52f' and owner_id is null;
update exercises set cue = 'Stand with the ball of one foot on a step and let the heel sink slowly below it.', description = 'Stand on the edge of a step with the ball of one foot on it and the heel hanging. Hold a rail or wall for balance. Let your heel drop slowly with a straight knee until you feel the stretch in the calf. Hold it there. Don''t bounce. Then switch feet.' where id = 'ed5b6822-3404-4ccd-9d05-14a2278d99cd' and owner_id is null;
update exercises set cue = 'Start on hands and knees, round your back up, then arch it down, moving with your breath.', description = 'Get on all fours with your hands under shoulders and knees under hips. Breathe out and round your spine up toward the ceiling, tucking your chin. Breathe in and drop your belly, lifting your chest and tailbone. Move slowly through the whole spine. Don''t force the end of the range.' where id = '5b9fc1d4-db97-4cc0-bbba-e6210c5e8085' and owner_id is null;
update exercises set cue = 'Sit tall and tilt your ear toward your shoulder, keeping the other shoulder down.', description = 'Sit or stand with your shoulders relaxed. Tilt your head so your ear moves toward your shoulder. Let the weight of your head do the work, or rest a light hand on the side of the head. Keep the opposite shoulder pulled down. Don''t turn your head or shrug. Hold, then switch sides.' where id = 'c35f433c-0062-4e43-8956-22a87dd9a1e1' and owner_id is null;
update exercises set cue = 'Sit back on your heels, stretch your arms forward, and rest your forehead on the floor.', description = 'Kneel on the mat with your big toes touching and your knees wide. Sit your hips back toward your heels and walk your hands forward. Let your forehead rest down. Breathe slowly into your lower back. If your hips don''t reach your heels, put a pillow underneath.' where id = '76a1da93-ff31-4215-b928-731a0b4914b2' and owner_id is null;
update exercises set cue = 'Pull your chin straight back, like making a double chin, without tilting your head.', description = 'Sit or stand tall and look straight ahead. Slide your chin straight back without tilting up or down. Hold for a second, then relax. Think of making a double chin. Keep your eyes level. Don''t push so hard that it hurts.' where id = '4db1d930-92bf-46cf-a0c7-8b1d1a30d324' and owner_id is null;
update exercises set cue = 'Lie on your side with knees bent and feet together, then open the top knee like a clamshell.', description = 'Lie on your side with your hips and knees bent and the band above your knees. Keep your feet together and stacked. Lift the top knee as high as you can without rolling your hips backward. Lower slowly. Keep your hips stacked. Finish the reps, then switch sides.' where id = 'ed99f143-14f7-413e-9755-86e8d243c32e' and owner_id is null;
update exercises set cue = 'Lie on your belly, put your hands under your shoulders, and press your chest up.', description = 'Lie face down with your hands flat beside your chest. Press up through your hands, lifting your chest while keeping your hips on the floor. Keep your shoulders away from your ears. Breathe slowly. Don''t crunch your lower back. Only go as high as feels comfortable.' where id = '9ac0261a-7e08-472b-82eb-a4c454db60af' and owner_id is null;
update exercises set cue = 'Lie on your side with your top foot on a bench and lift your hips so your body is straight.', description = 'Lie on your side next to a bench. Put your top leg on the bench with the inner knee or foot against it, and your forearm under your shoulder. Lift your hips until your body is in a line. Keep your bottom leg under the bench. Don''t let your hips sag. Hold, then switch sides.' where id = '1a987455-9e98-4980-96af-d645f143d5d9' and owner_id is null;
update exercises set cue = 'Put one knee behind you on the floor, foot up on a couch, and sink your hips forward.', description = 'Kneel with your back foot up against a couch or wall. Step the other foot forward into a lunge. Squeeze the glute of the back leg and press your hips forward. Stay tall with your chest up. Don''t arch your lower back. Hold, then switch sides.' where id = 'dcacbeb5-c7f3-4882-8742-35e8d32f2c32' and owner_id is null;
update exercises set cue = 'Reach your right arm behind your back and gently pull it upward with the other hand.', description = 'Stand tall and reach your right hand behind your back with the palm facing out. Use a towel or your left hand to gently pull the right hand upward. Keep your shoulders square and your chest forward. Stop at a mild stretch. Don''t lean forward or twist.' where id = 'b5f1606a-44e4-4901-ba33-493048211c03' and owner_id is null;
update exercises set cue = 'Bring one arm across your chest and pull it close with the other hand.', description = 'Stand tall and raise one arm across your body at shoulder height. Hold it above the elbow with your other hand and pull it toward your chest. Keep your shoulders down. Don''t twist your body. Hold, then switch arms.' where id = '84dfd89f-fb5c-4e3e-9981-3c581466bb84' and owner_id is null;
update exercises set cue = 'Lie on your back, arms up, knees over hips, then lower opposite arm and leg and return.', description = 'Lie on your back with your arms straight up and your knees bent over your hips. Press your lower back lightly into the floor. Reach one arm back and lower the opposite leg at the same time. Return and switch. Don''t let your back arch off the floor.' where id = '8b89c621-2a04-41d0-9c28-4f57285564a1' and owner_id is null;
update exercises set cue = 'Step into a deep lunge, drop your hips low, and press your elbow toward the floor.', description = 'Start in a lunge with your front foot between your hands. Sink your hips down and forward. Drop your back knee or keep it lifted. Press the inside of your front knee out with your elbow. Keep your chest up. Don''t let your front knee collapse in. Hold, then switch sides.' where id = 'f6f18285-d191-4287-8c0a-77c37a5f9217' and owner_id is null;
update exercises set cue = 'Sit into a deep squat with your heels down and hold it for a few minutes.', description = 'Stand with your feet a bit wider than your hips and toes turned out. Squat as low as you can, keeping your heels on the floor. Press your elbows out against your knees and keep your chest up. Shift around when you need to. Hold onto a post if you can''t stay down.' where id = 'abc47c5a-0b14-437a-99b8-3de64dfeb6a1' and owner_id is null;
update exercises set cue = 'Stand in a doorway with your forearm on the frame and step through until you feel your chest stretch.', description = 'Stand in a doorway with your elbow bent at 90 degrees and your forearm on the frame. Step the same-side foot forward and let your chest open. Keep your ribs down and your shoulder away from your ear. Stop at a mild stretch. Don''t arch your back. Hold, then switch arms.' where id = 'f2d0b99d-5b32-452a-9366-9ac81b411e15' and owner_id is null;
update exercises set cue = 'Go from hands and knees into an inverted V, pushing your hips up and back.', description = 'Start on hands and knees with your toes tucked under. Press your hips up and back so your body forms a V. Spread your fingers and push the floor away. Bend your knees if your back rounds. Let your heels reach toward the floor. Hold and breathe slowly.' where id = 'ea36887a-72b0-4d15-8370-1a0328c202e0' and owner_id is null;
update exercises set cue = 'Stand on the edge of a step and slowly lower your heel on one leg.', description = 'Stand with the balls of both feet on a step. Rise up on both feet, shift your weight to one foot, and lower slowly for three seconds. Keep the knee straight. Use both feet to get back up. Don''t drop quickly. Finish the reps, then switch legs.' where id = 'de4f8f62-7498-4c5e-bcb2-1a399b35653e' and owner_id is null;
update exercises set cue = 'Pull the rope toward your face with your elbows high and spread the ends apart.', description = 'Set the cable at upper chest height with a rope. Grab it with your palms facing in and step back. Pull the rope toward your face, elbows high, and spread your hands apart at the end. Squeeze your shoulder blades. Don''t lean back or shrug. Return slowly.' where id = 'eac16892-a7fc-4f45-93c1-0e27caa2f284' and owner_id is null;
update exercises set cue = 'From hands and knees, lift one bent knee out to the side without twisting your hips.', description = 'Start on all fours with your hands under shoulders and knees under hips. Keep your knee bent and lift it out to the side like a dog at a hydrant. Keep your hips level and your back still. Lower slowly. Don''t rotate your trunk to get higher. Finish the reps, then switch legs.' where id = '7fd3fbfd-1726-467b-aba5-dfc8b4601028' and owner_id is null;
update exercises set cue = 'Lie on your side with the roller under the outside of your thigh and roll slowly hip to knee.', description = 'Lie on your side with the foam roller under the outside of your thigh. Support yourself on your forearm and the other foot. Roll slowly from just below the hip to above the knee. Stop and breathe on tender spots. Don''t roll over the knee joint. Then switch legs.' where id = 'e08f0fb4-547e-4ed3-9139-49c6db2d23ef' and owner_id is null;
update exercises set cue = 'Lie face down with the roller under your thighs and roll from hip to just above the knee.', description = 'Lie face down on your forearms with the foam roller under the front of your thighs. Roll slowly from the hip to just above the knee. Turn your feet slightly in and out to find different spots. Pause on tight areas. Don''t let your lower back sag. Then switch legs.' where id = '909106cf-2d7f-481f-a65d-2d1ecd97e37d' and owner_id is null;
update exercises set cue = 'Stand barefoot and lift your arch by pulling the ball of your foot toward your heel, toes flat.', description = 'Stand on one foot, barefoot, with your toes relaxed. Pull the ball of your foot back toward your heel so the arch lifts. Keep your toes flat on the floor. Hold for ten seconds. Don''t curl your toes. Then switch feet.' where id = '8c982b40-80e4-475c-87a5-b5007566acfb' and owner_id is null;
update exercises set cue = 'Get on hands and knees, spread your knees wide, and sit back with your hips over your heels.', description = 'Get on all fours on a mat and slide your knees out as wide as you can. Keep your ankles in line with your knees. Lower onto your forearms and sit your hips back. Breathe slowly. Don''t force the stretch. Use padding under your knees if it hurts.' where id = 'c15761ff-7f71-48f5-bd63-78dd652323fd' and owner_id is null;
update exercises set cue = 'Lock your feet under the pads and lower your body toward the floor, then curl back up with your hamstrings.', description = 'Set your feet against the foot plate and your knees on the pad, hips just in front. Lower your torso forward under control. Use your hamstrings and glutes to pull yourself back up. Keep your body in a line from knees to shoulders. Don''t bend at the hips.' where id = '90db04fb-5c1a-4e99-8ee1-d6d831ed2a10' and owner_id is null;
update exercises set cue = 'Kneel on one knee and rock forward until your front knee moves over your toes, keeping the heel down.', description = 'Kneel on one knee with the other foot flat on the floor in front. Keep your front heel down and rock your knee forward over your toes. Come back slowly. Keep your chest up. Don''t let your heel lift or your arch collapse. Finish the reps, then switch legs.' where id = '08120a15-88a0-4ec3-ae42-650dbec17076' and owner_id is null;
update exercises set cue = 'Kneel on one knee, squeeze your back glute, and reach the same-side arm up and over.', description = 'Kneel on one knee with a cushion under it. Tuck your pelvis slightly and squeeze the back glute. Reach the same-side arm overhead and lean away slightly. Keep your ribs down. Don''t arch your lower back. Hold, then switch sides.' where id = '398dca45-0072-43ac-96f0-3dacfd16940c' and owner_id is null;
update exercises set cue = 'Stand tall and draw circles with your knee, moving from the hip.', description = 'Stand holding a wall or rail with one leg lifted. Bend your knee to about hip height. Draw large slow circles with the knee, keeping your pelvis still. Go one way, then the other. Don''t swing from your lower back. Then switch legs.' where id = '747babdf-34fc-42ef-bd9a-36ec2e772cec' and owner_id is null;
update exercises set cue = 'Hold a light weight, hinge forward and curl your spine down one bone at a time, then roll back up.', description = 'Stand with a light weight held close to your chest. Tuck your chin and curl down slowly, one segment at a time, letting your hands hang. Go only as low as is comfortable. Reverse the move and stack your spine back up. Don''t rush. Use a very light weight.' where id = '859da98f-4773-405e-a31e-ece554cd2f5e' and owner_id is null;
update exercises set cue = 'Lie on your back, pull one knee to your chest, and keep the other leg flat on the floor.', description = 'Lie on your back with both legs straight. Bend one knee and pull it toward your chest with both hands. Keep the other leg flat on the floor and your lower back down. Breathe slowly. Don''t lift your head. Hold, then switch legs.' where id = '33c26ce9-8110-406d-93cb-2bdac01dff38' and owner_id is null;
update exercises set cue = 'Put a band above your knees, bend a little, and step sideways with your feet pointing forward.', description = 'Place the band above your knees and sit into a quarter squat. Step sideways with the lead foot and follow with the other. Keep tension on the band the whole time. Keep your toes forward and knees out. Don''t let your knees cave. Go ten steps, then come back.' where id = '2de90e16-3978-4955-b060-d10a8fb7ce3a' and owner_id is null;
update exercises set cue = 'Stand on one leg and swing the other forward and back like a pendulum.', description = 'Stand tall with one hand on a wall. Swing the leg forward and back, letting it get a little higher each time. Keep your torso upright and your standing knee soft. Don''t let your back arch as the leg goes behind you. Finish the reps, then switch legs.' where id = '2a1b6d97-dc44-40de-901e-e60a5b4a4eb1' and owner_id is null;
update exercises set cue = 'Tilt your ear toward your shoulder while gently turning your nose toward your armpit.', description = 'Sit tall and turn your head about 45 degrees toward one armpit. Gently tilt your chin toward your chest. Rest a light hand on the back of your head to add a bit of weight. Keep the opposite shoulder down. Don''t pull hard. Hold, then switch sides.' where id = '9bc730ca-8711-42f1-9422-77fa3ad46931' and owner_id is null;
update exercises set cue = 'Put a band above your knees, stay low, and step diagonally forward and back like a monster.', description = 'Place the band around your legs above the knees and sit into a quarter squat. Step diagonally forward with one foot, then the other, keeping your feet wide. Stay low and keep your toes pointing forward. Don''t let your knees cave in. Walk forward for ten steps, then back.' where id = '32d7ef87-1ee6-4ac2-a492-dbaaf20d9720' and owner_id is null;
update exercises set cue = 'Press your hand against your head and push back with your neck, holding for ten seconds in each direction.', description = 'Put your palm on your forehead and press your head into your hand without moving. Hold for ten seconds. Repeat on each side and the back of the head. Keep your jaw relaxed and your shoulders down. Push gently, not hard. Don''t hold your breath.' where id = '6637c3cc-0d01-4283-9c27-d0f7598a4862' and owner_id is null;
update exercises set cue = 'Slowly turn your head to look over one shoulder and back to the other.', description = 'Sit or stand tall with your shoulders down. Slowly turn your head to look over one shoulder, as far as is comfortable. Pause, then turn to the other side. Keep your chin level. Don''t tilt your head or shrug. Move gently and breathe.' where id = '9ddc07c2-8fcb-4b84-9db7-98e60d1e228f' and owner_id is null;
update exercises set cue = 'Turn your head slowly to one side as far as it goes, then slowly to the other.', description = 'Sit or stand tall with your shoulders relaxed. Turn until you feel a gentle stop, pause, and come back through the middle to the other side. Don''t shrug or twist your chest to cheat the turn.' where id = 'e6b12814-0615-46f3-8b88-bb8ca9087438' and owner_id is null;
update exercises set cue = 'Lie on your back and nod your chin down like you''re saying yes, then hold it.', description = 'Keep the back of your head resting on the floor. Make a small nod, as if you''re lengthening the back of your neck. Hold for ten seconds. Don''t lift your head or jam your chin toward your chest.' where id = 'f92e43dd-28bc-4e48-aeaa-d78a398e3029' and owner_id is null;
update exercises set cue = 'Put one hand on a bench, pull the dumbbell up to your hip, and lower it slowly.', description = 'Start with the left arm, then switch. Keep your back flat and your neck in line with your spine. Pull your elbow back instead of lifting with your shoulder. Don''t twist your torso to swing the weight up.' where id = 'ed6489fd-ce6e-4c13-b386-beca676e53fc' and owner_id is null;
update exercises set cue = 'Pick up a heavy dumbbell in each hand and walk tall without letting your shoulders creep up.', description = 'Stand with the weights at your sides and your chin level. Take steady steps for about 40 meters. Everyone lets their shoulders rise toward their ears as they tire. Keep them down.' where id = 'a9184b7a-e4e5-4e79-9540-dbb88d9335eb' and owner_id is null;
update exercises set cue = 'Press your head into your hand and don''t let it move, front, back, and both sides.', description = 'Put your palm on your forehead and push gently while your neck pushes back. Hold ten seconds, then do the same on each side and the back of your head. Keep the push light and steady, not a jerk.' where id = 'dc7521d7-ae7b-4e51-a38e-b2afefa23bc4' and owner_id is null;
update exercises set cue = 'Lie face down, lift your head slowly until it''s in line with your body, then lower it.', description = 'Rest your forehead off the edge of a bed or just above the floor. Lift only until your neck is neutral. Don''t crank your head back to look at the ceiling.' where id = 'b50418d5-f491-4efc-8561-4ca468558097' and owner_id is null;
update exercises set cue = 'Sit with a chair back across your upper back and lean over it, letting your chest open up.', description = 'Put your hands behind your head to support your neck. Lean back over the top of the chair at the level of your shoulder blades. Move up or down the spine a bit between reps. Don''t let your lower back do the bending.' where id = '21f39759-e61a-4d42-987e-603ba4e9bdab' and owner_id is null;
update exercises set cue = 'Tilt your ear toward your shoulder, turn your nose toward your armpit, and let your head weigh it down.', description = 'Start with the left side. Sit tall and hold the seat with your same-side hand to keep that shoulder down. Breathe for thirty seconds, then switch sides. Don''t yank on your head.' where id = '4be70c46-c55f-4e02-bc84-d0c32404e110' and owner_id is null;
update exercises set cue = 'Kneel with your feet anchored and lower your body forward as slowly as you can.', description = 'Keep your body in one straight line from knees to head and your hips open. Catch yourself with your hands at the bottom, then push back up. Don''t fold at the hips.' where id = 'c0d5f73c-b7fc-4e46-b781-8bf80754bfb8' and owner_id is null;
update exercises set cue = 'Bring one shin across in front of you, slide the back leg long, and fold forward over it.', description = 'Start with the left leg in front. Keep your hips pointing at the floor as much as you can. Use your hands or a pillow under you if the hip is high. Don''t force the front knee down. Hold, then switch.' where id = 'c3a8b7e6-59e4-49a2-b68f-4f983659b290' and owner_id is null;
update exercises set cue = 'From a plank, tap one shoulder with the opposite hand, then switch, without rocking your hips.', description = 'Spread your feet wider than usual to stay steady. Tap with the left hand first. Squeeze your glutes and keep your hips level. If your hips swing side to side, slow down.' where id = 'c98bcca5-31d2-4093-87c8-72c7547ade1e' and owner_id is null;
update exercises set cue = 'Lie on your back, loop a strap on your raised leg, push into it, then relax and pull closer.', description = 'Do the left leg first. Push your heel into the strap for about five seconds, let go, and gently pull the leg higher. Keep the other leg flat on the floor. Don''t bend the knee of the leg you''re stretching.' where id = '9bd9afc4-b85a-4fe0-bd0b-7194b2dc450c' and owner_id is null;
update exercises set cue = 'Lie face down, pull your chin straight back, then lift your head a little.', description = 'Think of making a double chin against the floor first. Then raise your forehead just slightly and lower it. Keep the movement small. Don''t push your chin forward.' where id = '464ec67b-55e0-4037-8f52-41b4e738cb2b' and owner_id is null;
update exercises set cue = 'Do a push-up, and at the top reach one arm straight out in front of you.', description = 'Start with the left arm reaching. Keep your hips square and don''t let them twist. Place your feet a little wider to stay steady. If you rock side to side, slow the reach down.' where id = '58e737b0-4918-4bf2-90a5-486600da87d7' and owner_id is null;
update exercises set cue = 'Hold a band wide in front of you and swing it overhead and down behind you with straight arms.', description = 'Grip as wide as you need so your elbows stay straight. Go slowly and keep your ribs from flaring. Move your hands closer only when it feels easy. Don''t arch your back to get the band past.' where id = 'a2d80f01-35e0-4d69-8e82-6aae75345322' and owner_id is null;
update exercises set cue = 'Kneel tall and lean back slowly from your knees, then pull yourself back up.', description = 'Keep your body in one straight line from knees to head. Go only as far as you can control. Squeeze your glutes. Don''t bend at the hips or sit back onto your heels.' where id = 'f1f4937e-fff9-4357-96b8-bbb157fbb158' and owner_id is null;
update exercises set cue = 'Rest your forearm on your thigh, palm down, and curl the weight up by bending your wrist back.', description = 'Let the dumbbell drop slowly at the bottom. Keep your forearm still and let only your wrist move. Use a light weight. Don''t swing it up.' where id = '3a281f8e-11cf-4229-93f4-36afe796a7fd' and owner_id is null;
update exercises set cue = 'Sit tall, tuck one hand under your collarbone, and tilt your head away and slightly back.', description = 'Start with the left side. Press your collarbone down lightly with your hand. Breathe slowly for thirty seconds, then switch. Don''t pull your head with your other hand.' where id = '7237d518-6315-488c-b823-4e1156740231' and owner_id is null;
update exercises set cue = 'Put your forearms on the wall and slide them up, keeping your shoulder blades moving smoothly.', description = 'Stand close with your forearms flat on the wall. Slide up until you feel your upper back working, then come back down. Don''t shrug your shoulders or let your lower back arch.' where id = 'e50ce8d2-afd3-483d-ae22-7e4be8430e7a' and owner_id is null;
update exercises set cue = 'Sit with a band looped around the top of your foot and pull your toes up toward your shin.', description = 'Do the left foot first, then switch. Keep your heel on the floor and your leg straight. Pull up, hold a beat, and lower slowly. Don''t let your knee roll in or out.' where id = '0b153a34-0855-40eb-aef0-20760b519070' and owner_id is null;
update exercises set cue = 'Sit on a bench, rest one ankle on the other knee, and lean forward with a flat back.', description = 'Start with the left ankle on the right knee. Press your knee away gently with your hand. Lean from your hips, not by rounding your back. Hold, then switch.' where id = '33dd31cb-ff6d-4e6f-b463-1c3c82443f60' and owner_id is null;
update exercises set cue = 'Sit with your legs wide apart and walk your hands forward as far as feels comfortable.', description = 'Keep your toes pointing up and your knees straight. Hinge from your hips, not your upper back. Hold the stretch and breathe. Don''t force your chest to the floor.' where id = '272d11d0-c25c-4ae8-87b4-21c4f4de1bde' and owner_id is null;
update exercises set cue = 'Make the biggest slow circle you can with your arm, moving only at the shoulder.', description = 'Do the left arm first, then switch. Keep your ribs and hips still. Take your arm up, back, and around as one smooth circle. Don''t lean your body to make the circle bigger.' where id = '19aa9f7a-e6b2-4c24-82de-2f635fafaa89' and owner_id is null;
update exercises set cue = 'Hang from a bar and pull your shoulder blades down away from your ears without bending your elbows.', description = 'Hold the bar with a firm grip and straight arms. Pull yourself up a couple of inches using only your shoulders. Hold. Don''t bend your elbows or kick your legs.' where id = 'aa84dd5d-f763-4a45-a7f2-78210420eff5' and owner_id is null;
update exercises set cue = 'Hold a band in front of you and pull it apart until your hands reach your sides.', description = 'Keep your arms straight and level with your chest. Squeeze your shoulder blades together at the end. Don''t shrug or lean back.' where id = '6d83463a-b652-4e40-8876-8ccd2407996e' and owner_id is null;
update exercises set cue = 'Lift your elbow out to the side at shoulder height and rotate your hand up against the band.', description = 'Do the left arm first. Keep your elbow bent at ninety degrees and fixed in place. Turn your hand up like you''re raising a stop sign, then lower slowly. Don''t let your elbow drop.' where id = 'd9e3563f-6554-4fb8-b670-c1a094d54adc' and owner_id is null;
update exercises set cue = 'Hold a kettlebell upside down at shoulder height and walk, keeping the bell perfectly still.', description = 'Start with the left arm, then switch. Grip the handle tight and keep your wrist straight. Keep your elbow tucked near your ribs. If the bell tips, lighten the weight.' where id = 'dc3cfd82-ac4b-4085-b0f1-ec9c9aec0a8e' and owner_id is null;
update exercises set cue = 'Hold a kettlebell upside down and press it overhead without letting it wobble.', description = 'Start with the left arm, then switch. Squeeze the handle hard and keep your wrist stacked over your elbow. Press slowly in a straight line. Don''t let the bell drift forward.' where id = '82a71cba-baf3-4e3a-8984-145f3c52dade' and owner_id is null;
update exercises set cue = 'Pull a band toward your face, with your elbows high and wide, then squeeze your shoulder blades back.', description = 'Anchor the band at eye height. Pull your hands to either side of your face. Rotate your hands back at the end. Don''t lean back to pull harder.' where id = '5b4956dc-1c90-432b-8eaa-975f572cc987' and owner_id is null;
update exercises set cue = 'Press the dumbbells overhead and bring them down until they''re level with your shoulders, then press again.', description = 'Keep your ribs down and your glutes squeezed. Lock your arms out fully at the top by your ears. Don''t arch your lower back to get the weight up.' where id = '649c6199-6d8a-4f6c-a668-e0b0fbee0806' and owner_id is null;
update exercises set cue = 'Hang from a bar with your arms straight and let your shoulders stretch and your body hang loose.', description = 'Hold on with both hands and relax your shoulders up toward your ears. Breathe slowly. Keep your feet off the floor or bend your knees. Let go if your grip fails.' where id = 'c39d432e-8fc0-4001-b0a3-6fa80026300f' and owner_id is null;
update exercises set cue = 'Lie face down with your arms out to the sides and lift them up, squeezing your shoulder blades together.', description = 'Keep your thumbs pointing up and your forehead off the floor. Lift your arms from your upper back, then lower slowly. Don''t lift with your neck.' where id = '1bfab813-5a51-4ff7-b2bf-bbc3d1db1391' and owner_id is null;
update exercises set cue = 'Lie face down with your elbows bent and pull your arms back into a W, squeezing your shoulder blades.', description = 'Start with your hands by your head and pull your elbows toward your hips. Lift up, hold a beat, and lower. Don''t shrug your shoulders toward your ears.' where id = 'cf6fdadb-2db4-4ce7-a0ee-f367d66a1bc3' and owner_id is null;
update exercises set cue = 'Lie face down with your arms overhead in a Y and lift them off the floor.', description = 'Keep your thumbs pointing up. Lift from your upper back, not your lower back. Go slowly and lower under control. Don''t lift your chest off the floor.' where id = '3d786f53-b0a1-401e-91ff-2edc849d2833' and owner_id is null;
update exercises set cue = 'Press your forearms into the wall against a band and slide them up, pushing the wall away.', description = 'Loop the band around your forearms. Push out into the band as you slide up. Keep your ribs down. Don''t let your shoulder blades wing out or your lower back arch.' where id = 'eb1a9704-3164-425f-aa9f-74b1f76898e4' and owner_id is null;
update exercises set cue = 'Lie back on a foam roller under your upper back and let your chest open over it.', description = 'Support your head with your hands. Move the roller to a new spot between your shoulder blades after each rep. Don''t let your ribs flare or your lower back arch.' where id = '190d25e1-569f-4469-bbf0-0b2ec55d05a1' and owner_id is null;
update exercises set cue = 'Stand with your back to the wall and slide your arms up and down, hands and elbows touching.', description = 'Keep your head and lower back touching the wall. Slide up as far as you can without losing contact. Don''t arch your back to get higher.' where id = 'cc6481af-15ba-46c6-af71-6132deb7ce0b' and owner_id is null;
update exercises set cue = 'Lie on your side and lift your bottom leg toward the ceiling, then lower it slowly.', description = 'Do the left side first. Cross your top leg in front or bend it behind you. Keep your bottom leg straight and your hips stacked. Don''t roll your hips backward.' where id = '6d42cae8-b84d-4ab6-93f6-cdd3a1106b3c' and owner_id is null;
update exercises set cue = 'Stand on one leg, pull the band to your ribs, and reach the other arm forward.', description = 'Start with the left leg. Hinge forward with a flat back. Row, then reach, then lower slowly. Don''t let your hips twist or your standing knee collapse inward.' where id = '0e842306-3881-47f6-a875-625b29ac155b' and owner_id is null;
update exercises set cue = 'Stand on one foot, close your eyes, and stay as still as you can.', description = 'Start on the left leg, then switch. Keep a slight bend in your standing knee. Stand next to a wall in case you need to catch yourself. Don''t hop or hold your breath.' where id = '1c2e9b44-1d95-4b34-a268-dc03690f6824' and owner_id is null;
update exercises set cue = 'Stand on one foot on a pillow or foam pad and hold still.', description = 'Start on the left leg, then switch. Look at a spot ahead of you and keep your standing knee slightly soft. Your foot and ankle will wobble a lot. That''s the point. Don''t lock your knee.' where id = '1e7426e9-3402-4840-9057-acfa62e70be1' and owner_id is null;
update exercises set cue = 'Stand on one foot, close your eyes, and stay as still as you can.', description = 'Start on the left leg, then switch. Keep your hips level and your standing knee soft. Stay near a wall for safety. Don''t let your lifted foot touch your standing leg.' where id = '6f5bb3cc-5032-4250-92ed-a0f4bb41ddef' and owner_id is null;
update exercises set cue = 'Stand on one leg, hinge forward, and reach your hand to a cone on the floor.', description = 'Start with the left leg. Send your other leg straight back behind you. Keep your back flat. Touch the cone, then stand back up. Don''t let your hips open toward the side.' where id = '0d72889e-5999-4a37-a72a-55f26cae8131' and owner_id is null;
update exercises set cue = 'Stand on one leg, hold a dumbbell, and hinge forward while your other leg goes straight back.', description = 'Start with the left leg. Keep a soft knee and a flat back. Lower the weight along your leg and stand up by squeezing your glutes. Don''t round your back.' where id = '585f0978-f638-48c2-9197-1e45b2302a6e' and owner_id is null;
update exercises set cue = 'Face the sled, hold the straps, and walk backward, dragging it with you.', description = 'Keep your chest tall and take steady steps, pushing through your whole foot. Stay low with your knees bent. Don''t lean back or take short, choppy steps.' where id = '856d8229-dff5-4508-8ec4-92fc56390e75' and owner_id is null;
update exercises set cue = 'Lie on your right side, elbow bent in front, and gently press your right wrist toward the floor.', description = 'Keep your upper arm at ninety degrees to your body. Use your left hand to press softly. Stop when you feel a stretch in the back of your shoulder. Don''t push into pain or roll your body forward.' where id = 'da654dd2-ca49-4690-a0f9-326ef621a374' and owner_id is null;
update exercises set cue = 'Fold forward from your hips and let your arms hang and reach overhead toward the floor.', description = 'Clasp your hands behind your back first, then let them fall over your head. Bend your knees as much as you need. Breathe. Don''t round your back to get your hands lower.' where id = '4e9d97a5-e784-4db7-89fe-fad5019a0320' and owner_id is null;
update exercises set cue = 'Put one heel out in front, hinge forward with a flat back, and feel the back of that leg.', description = 'Start with the left leg. Keep your front knee almost straight. Lean from your hips and keep your chest up. Don''t round your back or lock your knee hard.' where id = '4059fb17-1197-406c-aa1f-c65e20e70342' and owner_id is null;
update exercises set cue = 'Step into a lunge, squeeze the glute of your back leg, and press your hips forward.', description = 'Do the left leg back first. Tuck your pelvis under so your lower back stays flat. Stay tall. Don''t arch your back or let your front knee cave in.' where id = '6b2b921e-eb95-4d25-940c-c84672cbb76c' and owner_id is null;
update exercises set cue = 'Stand on one leg, grab the other foot behind you, and pull your heel toward your glute.', description = 'Start with the left leg lifted. Keep your knees close together and your hips pushed slightly forward. Stand tall. Don''t arch your lower back.' where id = 'f5e02d57-67c8-4c6e-b742-b7f7a62b877e' and owner_id is null;
update exercises set cue = 'Fold forward and reach your hands toward your toes, then thread one hand under between your legs.', description = 'Bend your knees as much as you need. Alternate sides each rep. Move slowly and let your head hang. Don''t bounce to get lower.' where id = 'dcb26413-fa6d-4f15-9145-88612ecbbb13' and owner_id is null;
update exercises set cue = 'Pedal at an easy pace where you can still talk the whole time.', description = 'Set the seat so your knee is slightly bent at the bottom of each pedal stroke. Keep your shoulders relaxed. Spin at a steady pace for twenty to thirty minutes. Don''t grip the handlebars hard.' where id = 'db2dd277-738f-4d7d-9a91-2fa131a4e6c6' and owner_id is null;
update exercises set cue = 'Lie on your back with a massage ball under the base of your skull and let your head rest.', description = 'Find the tight spots at the base of your skull. Rest there and gently nod your head yes or turn it no. Breathe slowly. Don''t press hard or roll quickly.' where id = '4b8bbf7a-7bb8-48a6-a595-2b7ab0408d22' and owner_id is null;
update exercises set cue = 'Stand with one foot right in front of the other, heel to toe, and stay still.', description = 'Start with the left foot in front, then switch. Look at a spot ahead of you. Keep your arms out if you need them. Don''t let your hips sway.' where id = '86582b64-e862-4a3b-b426-fa359ba1b78d' and owner_id is null;
update exercises set cue = 'Loop a band behind your knee and straighten your leg fully, squeezing your thigh.', description = 'Start with the left leg. Face the band''s anchor. Start with a slight bend, then press back until your knee is straight. Squeeze the front of your thigh. Don''t lean back.' where id = '1dd3b6ba-9e84-4c33-9657-9e555ac94b80' and owner_id is null;
update exercises set cue = 'Lie back on a foam roller under your upper back and let your chest open over it.', description = 'Put your hands behind your head and keep your hips on the floor. Lean back over the roller, pause, and come up. Move the roller a bit up or down between reps. Don''t let your lower back arch.' where id = '235ff191-27b5-46da-b9cd-6c199cc755e2' and owner_id is null;
update exercises set cue = 'Lie on your side with your knees stacked and rotate your top arm open toward the floor behind you.', description = 'Start with the left side on the floor. Keep your knees together and your hips still. Let your eyes follow your hand. Don''t let your knees slide apart.' where id = 'bb649b53-1259-4bae-a961-29498f9106bd' and owner_id is null;
update exercises set cue = 'From all fours, slide one arm under your body and rest your shoulder on the floor.', description = 'Start with the left arm. Keep your hips over your knees. Slide through, pause, then reach the arm up to the ceiling. Don''t sit your hips back.' where id = '9a6bf93c-6509-46ec-9d83-d73dde403616' and owner_id is null;
update exercises set cue = 'Lift your big toe off the floor while the other toes stay down, then switch.', description = 'Sit or stand with your foot flat. Lift the big toe only, then press it down and lift the other four. Start with the left foot. Don''t curl your toes or lift your heel.' where id = '8f936ba6-d46e-4685-9564-470c548e196d' and owner_id is null;
update exercises set cue = 'Hold a towel behind your back with one hand high and one low, and pull gently up on the towel.', description = 'Start with the left arm on top. Pull up with the top hand to stretch the bottom shoulder. Stand tall and don''t arch your back. Don''t yank on the towel.' where id = 'c31f85a1-bfe4-41ba-9014-acf86f0b0fec' and owner_id is null;
update exercises set cue = 'Sit tall, tilt your ear toward your shoulder, and let your hand rest gently on your head.', description = 'Start with the left ear down. Keep the opposite shoulder pressed down. Breathe for thirty to forty-five seconds, then switch. Don''t pull hard on your head.' where id = '856d2627-e1aa-407c-82c7-85d59771fc13' and owner_id is null;
update exercises set cue = 'Put your toes a few inches from the wall and push your knee to touch it, heel down.', description = 'Do the left foot first, then switch. Move your foot back to find the farthest distance you can touch. Measure it. Don''t let your heel lift or your knee cave inward.' where id = 'c745a26d-fce1-4766-9101-c85398d80f37' and owner_id is null;
update exercises set cue = 'Stand with your back against the wall, elbows bent, and slide your arms up and down.', description = 'Keep your elbows, wrists, and back of your hands on the wall. Slide up as far as you can with control. Don''t arch your lower back.' where id = 'd1ff7cf6-2512-41a6-b1ff-46d6df29f7b5' and owner_id is null;
update exercises set cue = 'Stand with your back and head against a wall and pull your chin straight back.', description = 'Keep your eyes level and your head touching the wall. Make a double chin without tilting your head down. Hold briefly, then relax. Don''t look down.' where id = 'f20d884a-5733-4eb9-9b16-7d5ee3d15659' and owner_id is null;
update exercises set cue = 'Put a plate on your knee and push your knee forward over your toes, keeping your heel down.', description = 'Start with the left foot. Take your time and keep your heel flat on the floor. Go as far as you can. Don''t let your arch collapse.' where id = '06eb6973-7e2c-419e-a383-736d1076e5d6' and owner_id is null;
update exercises set cue = 'Step into a deep lunge, put your hand down inside your foot, and rotate your chest open toward the ceiling.', description = 'Start with the left leg forward. Keep your back leg straight. Reach your top arm up and follow it with your eyes. Don''t let your front heel lift.' where id = '85672c89-db37-4d65-a18e-80f3e0c3437d' and owner_id is null;
update exercises set cue = 'Lie on your back, push up onto your head and feet, and hold with your hips high.', description = 'Keep your hands on the floor if you need them. Move slowly and stay on the top of your head. Don''t put weight on your neck or go further than feels safe.' where id = '3c48e29c-8ea5-4eca-9c13-37768df1a0c0' and owner_id is null;
update exercises set cue = 'Rest your forearm on your thigh, palm up, and curl the weight up by bending your wrist.', description = 'Let the dumbbell roll down toward your fingers, then curl it back up. Keep your forearm still and use a light weight. Don''t lift your arm off your leg.' where id = '59b48888-8541-42e8-a89b-81c425a00017' and owner_id is null;
update exercises set cue = 'Bend your wrists up, down, and in big circles, slowly, one direction at a time.', description = 'Hold your arms out or rest them on your knees. Do the left wrist first, then switch. Go as far as is comfortable. Don''t force the end of the range or rush the circles.' where id = 'b2e50b8e-d32a-46f4-81bf-919070850bf2' and owner_id is null;
update exercises set cue = 'Stand on one foot and reach your other foot forward, then to the back-left, then to the back-right.', description = 'Start on the left leg. Touch lightly, don''t rest your weight on the reaching foot. Keep your hips square. Return to the start between reaches. Don''t hop.' where id = '2af1471a-9a08-4e19-99ef-3a67d678f1a1' and owner_id is null;
update exercises set cue = 'Hinge forward with light dumbbells and raise your arms into a Y, then a T, then a W.', description = 'Keep your back flat and your neck long. Squeeze your shoulder blades with each shape. Use light weights. Don''t swing or shrug.' where id = '6896dbfe-ea81-4c7b-9638-2f4f196abc05' and owner_id is null;

